# PTX source for fp16 GEMM (C = A * Bᵀ) on SM80 (A100)
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry gemm_kernel(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // -------------------- registers --------------------
    .reg .pred   %p;
    .reg .s32    %tid_x, %tid_y, %bid_x, %bid_y;
    .reg .s32    %row, %col;
    .reg .u64    %A_ptr, %B_ptr, %C_ptr;
    .reg .u32    %M, %N, %K;
    .reg .s32    %k, %idx;
    .reg .f16    %a, %b;
    .reg .f32    %af, %bf, %acc;
    .reg .u64    %addr, %A_row_ptr, %B_row_ptr;

    // -------------------- load parameters --------------------
    ld.param.u64 %A_ptr, [A];
    ld.param.u64 %B_ptr, [B];
    ld.param.u64 %C_ptr, [C];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // -------------------- thread indices --------------------
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    mad.lo.s32 %row, %bid_y, %ntid.y, %tid_y;   // row = blockIdx.y * blockDim.y + threadIdx.y
    mad.lo.s32 %col, %bid_x, %ntid.x, %tid_x;   // col = blockIdx.x * blockDim.x + threadIdx.x

    // -------------------- bounds check --------------------
    setp.ge.s32 %p, %row, %M;
    @%p bra DONE;
    setp.ge.s32 %p, %col, %N;
    @%p bra DONE;

    // -------------------- accumulator init --------------------
    mov.f32 %acc, 0f00000000;

    // -------------------- compute base pointers --------------------
    // A_row_ptr = A + row * K * sizeof(half)
    mul.wide.s32 %addr, %row, %K;
    mul.wide.u64 %addr, %addr, 2;
    add.u64 %A_row_ptr, %A_ptr, %addr;

    // B_row_ptr = B + col * K * sizeof(half)   (B is stored as N×K)
    mul.wide.s32 %addr, %col, %K;
    mul.wide.u64 %addr, %addr, 2;
    add.u64 %B_row_ptr, %B_ptr, %addr;

    // -------------------- main K‑loop --------------------
    mov.s32 %k, 0;
LOOP:
    setp.ge.s32 %p, %k, %K;
    @%p bra END_LOOP;

    // load A[row, k]
    mul.wide.s32 %addr, %k, 2;
    mul.wide.u64 %addr, %addr, 1;
    add.u64 %addr, %A_row_ptr, %addr;
    ld.global.f16 %a, [%addr];

    // load B[col, k]
    mul.wide.s32 %addr, %k, 2;
    mul.wide.u64 %addr, %addr, 1;
    add.u64 %addr, %B_row_ptr, %addr;
    ld.global.f16 %b, [%addr];

    // convert to fp32
    cvt.f32.f16 %af, %a;
    cvt.f32.f16 %bf, %b;

    // accumulate
    fma.rn.f32 %acc, %af, %bf, %acc;

    add.s32 %k, %k, 1;
    bra LOOP;
END_LOOP:

    // -------------------- write result --------------------
    // convert accumulator to half
    cvt.rn.f16.f32 %a, %acc;

    // output index = (row * N + col)
    mul.lo.s32 %idx, %row, %N;
    add.s32 %idx, %idx, %col;
    cvt.u64.u32 %addr, %idx;
    mul.wide.u64 %addr, %addr, 2;          // byte offset
    add.u64 %addr, %C_ptr, %addr;
    st.global.f16 [%addr], %a;

DONE:
    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A, B):
        """
        A: torch.Tensor of shape (M, K), dtype=torch.float16, device='cuda'
        B: torch.Tensor of shape (N, K), dtype=torch.float16, device='cuda'
        Returns C = A @ B.T as torch.float16 tensor of shape (M, N)
        """
        import torch

        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb, "Inner dimensions must match"

        # Allocate output tensor
        C = torch.empty(M, N, dtype=torch.float16, device=A.device)

        # Kernel launch configuration (16×16 thread block)
        block = (16, 16, 1)
        grid = ( (N + block[0] - 1) // block[0],
                 (M + block[1] - 1) // block[1],
                 1 )

        # Arguments: raw pointers and dimensions
        args = [A.data_ptr(),
                B.data_ptr(),
                C.data_ptr(),
                M, N, K]

        # Launch the PTX kernel via the harness
        ptx_launch(self.module, "gemm_kernel", grid, block, args)

        return C
